begin; create temporary table prebook_code_fixture(prebook boolean,driver1_id uuid,load_company_code text); create trigger fixture_code before insert or update of driver1_id,prebook on prebook_code_fixture for each row execute function private.set_assigned_prebook_company_code(); do $$ declare v_driver uuid; begin select d.id into v_driver from public.drivers d join public.companies c on c.id=d.company_id where c.name ilike '%ap silver%' limit 1; if v_driver is null then raise exception 'Missing test driver'; end if; insert into prebook_code_fixture values(true,null,'BFP'); if exists(select 1 from prebook_code_fixture where load_company_code<>'BFP') then raise exception 'Unassigned changed'; end if; update prebook_code_fixture set driver1_id=v_driver; if exists(select 1 from prebook_code_fixture where load_company_code<>'AP') then raise exception 'Assigned code wrong'; end if; select d.id into v_driver from public.drivers d join public.companies c on c.id=d.company_id where c.name ilike '%jones freight%' limit 1; if v_driver is null then raise exception 'Missing reassignment driver'; end if; update prebook_code_fixture set driver1_id=v_driver; if exists(select 1 from prebook_code_fixture where load_company_code<>'JF') then raise exception 'Reassigned code wrong'; end if; insert into prebook_code_fixture values(false,v_driver,'BFP'); if not exists(select 1 from prebook_code_fixture where not prebook and load_company_code='BFP') then raise exception 'Non-prebook changed'; end if; end $$; rollback;
